vec2 Zoom = vec2(zoom,zoom);
vec2 Pan = vec2(1.0136,.31);
vec2 c = (uv - 0.5) * Zoom * uAspect - Pan;
vec2 v = 0.0 + sin(q5)*.05;
float m = 0;
const float r = 5;
float its = 30;
for (int n = 0; n < its; n++)
{
v = vec2(v.x * v.x - v.y * v.y, v.x * v.y * 2.0) + c;
if (dot(v, v) < (r*r - 1.0))
m++;
v = clamp(v, -r, r);
}
vec3 man = texture( sampler_main, v ).xyz;
vec3 color = texture( sampler_rand02, v ).xyz;
if (m == its)
ret = 0;
else
ret = (vec4(sin(m / 4.0+q1 * 3.0), sin(m / 5.0-q2 * 3.0), sin(m / 7.0+q22), 1.0 ) / 4.0 + 0.75);
ret = (ret*main*1.8
+ man * color)*.8;
//ret=man;
ret *= 0.98; //or try: ret -= 0.004;
}

